using System;using System.Threading.Tasks;using System.Windows.Input;
namespace PhotoBooth.Customer.UI.Mvvm { public sealed class AsyncCommand:ICommand { readonly Func<Task> action;readonly Func<bool> can;bool running;public AsyncCommand(Func<Task> action,Func<bool> can=null){this.action=action;this.can=can;}public bool CanExecute(object p)=>!running&&(can?.Invoke()??true);public async void Execute(object p){if(!CanExecute(p))return;running=true;NotifyCanExecuteChanged();try{await action();}finally{running=false;NotifyCanExecuteChanged();}}public event EventHandler CanExecuteChanged;public void NotifyCanExecuteChanged()=>CanExecuteChanged?.Invoke(this,EventArgs.Empty);} public sealed class RelayCommand:ICommand { readonly Action action;public RelayCommand(Action a){action=a;}public bool CanExecute(object p)=>true;public void Execute(object p)=>action();public event EventHandler CanExecuteChanged{add{}remove{}}} public sealed class ParameterCommand:ICommand { readonly Action<object> action;readonly Func<object,bool> can;public ParameterCommand(Action<object> action,Func<object,bool> can=null){this.action=action;this.can=can;}public bool CanExecute(object parameter)=>can?.Invoke(parameter)??true;public void Execute(object parameter)=>action(parameter);public event EventHandler CanExecuteChanged;public void NotifyCanExecuteChanged()=>CanExecuteChanged?.Invoke(this,EventArgs.Empty);} }
